        private const string Modifiers =
            "\u0000\u0654\u0000\u0655\u0000\u0658\u0000\u0658\u0000\u06dc\u0000\u06dc\u0000\u06e3\u0000\u06e3\u0000\u06e7\u0000\u06e8\u0000\u08ca\u0000\u08cb\u0000\u08cd\u0000\u08cf\u0000\u08d3\u0000\u08d3\u0000\u08f3\u0000\u08f3";

        private static int Scalar(string data, int p) => data[p] * 65536 + data[p + 1];
        internal static string JoiningType(int cp) {
            int lo = 0, hi = Joining.Length / 5 - 1;
            while (lo <= hi) { int m = (lo + hi) / 2, p = m * 5;
                if (cp < Scalar(Joining,p)) hi = m - 1;
                else if (cp > Scalar(Joining,p+2)) lo = m + 1;
                else return Joining[p+4].ToString(); }
            return "U";
        }
        internal static bool IsModifier(int cp) {
            for (int p = 0; p < Modifiers.Length; p += 4)
                if (cp >= Scalar(Modifiers,p) && cp <= Scalar(Modifiers,p+2)) return true;
            return false;
        }
